import { dogDepthIndependentSources, dogDepthSourceReview } from "./dog-depth-independent-sources";

// Eigene Vergleiche und Lernfälle. Der Geltungsbereich zusätzlicher
// Gegenprüfungen ist je Quelle und Lektion in sourceReview festgehalten.
const source = (label, url) => ({ label, url });
const fci = (name, number, group) => source(`FCI-Standard ${number}: ${name}`, `https://www.fci.be/Nomenclature/Standards/${String(number).padStart(3, "0")}g${String(group).padStart(2, "0")}-en.pdf`);
const refs = {
  nose: source("Craven, Paterson und Settles: Originalstudie zur Strömung beim Riechen, 2010", "https://pmc.ncbi.nlm.nih.gov/articles/PMC2871809/"),
  trials: source("JGHV: Originalordnung für Verbandszuchtprüfungen", "https://jghv.de/images/managed/dateien/2024/service/pruefungsordnungen-des-jghv/VZPO_2018_Druck_3.pdf"),
  reward: source("AVSAB: Was positive Verstärkung bedeutet", "https://avsab.org/talking-terms-positive-reinforcement/"),
  natural: source("AVSAB: Passende Aktivitäten als Belohnung", "https://avsab.org/use-natural-rewards-strategically/"),
  humane: source("AVSAB: Fachliche Stellungnahme zu tierschutzgerechter Ausbildung", "https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf"),
  efficacy: source("China, Mills und Cooper: Originalstudie zu Rückruf und belohnungsorientiertem Training, 2020", "https://www.frontiersin.org/journals/veterinary-science/articles/10.3389/fvets.2020.00508/full"),
  welfare: source("Vieira de Castro und andere: Originalstudie zu Trainingsmethoden und Tierwohl, 2020", "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0225023"),
};
const question = (q, right, a, b, c, explain) => ({ q, options: [right, a, b, c], answer: 0, explain });
const lesson = (id, title, paragraphs, takeaway, exercise, checks) => ({ id, title, paragraphs, takeaway, exercise, checks });
const countryNotes = {
  DE: "Biologie, Rassebegriffe und Lernprinzipien gelten als gemeinsame Wissensgrundlage. Jagdliche Eignungsnachweise, Ausbildungs- und Einsatzvoraussetzungen beim zuständigen Bundesland und Verband prüfen.",
  AT: "Rassestandards geben keine österreichische Einsatzfreigabe. Anerkennung, Ausbildung und jagdliche Anforderungen beim zuständigen Bundesland und Verband gesondert prüfen.",
  CH: "Rasseporträts vermitteln Wissen. Konkrete Ausbildungs-, Haltungs- und Einsatzanforderungen mit zuständigem Kanton und Fachverband abgleichen.",
};
function course(meta, lessons) {
  const sourceReview = dogDepthSourceReview[meta.id];
  const sourceIds = [...new Set((sourceReview?.lessons || []).flatMap(item => item.sourceIds))];
  const packs = lessons.map(item => ({ ...item, id: `${meta.id}-${item.id}`, sourceReview: sourceReview?.lessons.find(review => review.lesson === item.id) || null }));
  return {
    category: "Hundewesen", topic: "Hundewesen", imageKey: "hundewesen",
    countries: ["DE", "AT", "CH"], countryNotes, minutes: 55, level: "Vertiefung", reviewedOn: "2026-10-12", ...meta,
    sourceReview: sourceReview || null,
    sources: [...meta.sources, ...sourceIds.map(id => dogDepthIndependentSources[id]).filter(item => !meta.sources.some(existing => existing.url === item.url))],
    lessons: packs.map(({ checks, ...item }) => item),
    questions: packs.flatMap((item, lessonIndex) => item.checks.map((check, index) => {
      const answer = (lessonIndex + index) % 4;
      const options = [...check.options]; options.splice(answer, 0, options.shift());
      return { ...check, id: `${item.id}-frage-${index + 1}`, lessonId: item.id, options, answer };
    })),
  };
}

